document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("ohm-form"),t=document.getElementById("ohm-result");e&&e.addEventListener("submit",function(e){e.preventDefault();const n=parseFloat(document.getElementById("ohm-u").value),o=parseFloat(document.getElementById("ohm-i").value),a=parseFloat(document.getElementById("ohm-r").value);if(2!==[!isNaN(n),!isNaN(o),!isNaN(a)].filter(Boolean).length)return t.textContent="Please enter exactly two parameters.",void 0;if(isNaN(n))t.innerHTML=`<b>Voltage (U):</b> ${(o*a).toFixed(4)} V`;else if(isNaN(o)){if(0===a)return t.textContent="Resistance cannot be zero when calculating current.",void 0;t.innerHTML=`<b>Current (I):</b> ${(n/a).toFixed(4)} A`}else if(isNaN(a)){if(0===o)return t.textContent="Current cannot be zero when calculating resistance.",void 0;t.innerHTML=`<b>Resistance (R):</b> ${(n/o).toFixed(4)} Ω`}})});